		this.holiday_reference.list = structuredClone(Array.isArray(Calendar.CalcJP.holiday_reference) ? Calendar.CalcJP.holiday_reference : []);
		this.holiday_furikae1.list = structuredClone(Array.isArray(Calendar.CalcJP.holiday_furikae1) ? Calendar.CalcJP.holiday_furikae1 : []);
		this.holiday_kokumin.list = structuredClone(Array.isArray(Calendar.CalcJP.holiday_kokumin) ? Calendar.CalcJP.holiday_kokumin : []);
		this.holiday_furikae2.list = structuredClone(Array.isArray(Calendar.CalcJP.holiday_furikae2) ? Calendar.CalcJP.holiday_furikae2 : []);
		this.holiday_substitute.list = structuredClone(Array.isArray(Calendar.CalcJP.holiday_substitute) ? Calendar.CalcJP.holiday_substitute : []);
		this.holiday_observed.list = structuredClone(Array.isArray(Calendar.CalcJP.holiday_observed) ? Calendar.CalcJP.holiday_observed : []);

		// 祭日などの定義 ※基底クラスをオーバーライドする
		this.seasonFest_fixed.list = structuredClone(Array.isArray(Calendar.CalcJP.seasonFest_fixed) ? Calendar.CalcJP.seasonFest_fixed : []);
		this.seasonFest_movable.list = structuredClone(Array.isArray(Calendar.CalcJP.seasonFest_movable) ? Calendar.CalcJP.seasonFest_movable : []);
		this.seasonFest_seasonanchor.list = structuredClone(Array.isArray(Calendar.CalcJP.seasonFest_seasonanchor) ? Calendar.CalcJP.seasonFest_seasonanchor : []);
		this.seasonFest_holyweek.list = structuredClone(Array.isArray(Calendar.CalcJP.seasonFest_holyweek) ? Calendar.CalcJP.seasonFest_holyweek : []);
		this.seasonFest_cron.list = structuredClone(Array.isArray(Calendar.CalcJP.seasonFest_cron) ? Calendar.CalcJP.seasonFest_cron : []);
		this.seasonFest_reference.list = structuredClone(Array.isArray(Calendar.CalcJP.seasonFest_reference) ? Calendar.CalcJP.seasonFest_reference : []);

		// 予定日などの定義 ※基底クラスをオーバーライドする
		this.schedule_fixed.list = structuredClone(Array.isArray(Calendar.CalcJP.schedule_fixed) ? Calendar.CalcJP.schedule_fixed : []);
		this.schedule_movable.list = structuredClone(Array.isArray(Calendar.CalcJP.schedule_movable) ? Calendar.CalcJP.schedule_movable : []);
		this.schedule_cron.list = structuredClone(Array.isArray(Calendar.CalcJP.schedule_cron) ? Calendar.CalcJP.schedule_cron : []);
		this.schedule_reference.list = structuredClone(Array.isArray(Calendar.CalcJP.schedule_reference) ? Calendar.CalcJP.schedule_reference : []);

