		this.holiday_furikae1.list = structuredClone(Array.isArray(Calendar.CalcGB.holiday_furikae1) ? Calendar.CalcGB.holiday_furikae1 : []);
		this.holiday_kokumin.list = structuredClone(Array.isArray(Calendar.CalcGB.holiday_kokumin) ? Calendar.CalcGB.holiday_kokumin : []);
		this.holiday_furikae2.list = structuredClone(Array.isArray(Calendar.CalcGB.holiday_furikae2) ? Calendar.CalcGB.holiday_furikae2 : []);
		this.holiday_observed.list = structuredClone(Array.isArray(Calendar.CalcGB.holiday_observed) ? Calendar.CalcGB.holiday_observed : []);
		this.holiday_substitute.list = structuredClone(Array.isArray(Calendar.CalcGB.holiday_substitute) ? Calendar.CalcGB.holiday_substitute : []);

