		this.seasonFest_fixed.list = structuredClone(Array.isArray(Calendar.CalcGB.seasonFest_fixed) ? Calendar.CalcGB.seasonFest_fixed : []);
		this.seasonFest_movable.list = structuredClone(Array.isArray(Calendar.CalcGB.seasonFest_movable) ? Calendar.CalcGB.seasonFest_movable : []);
		this.seasonFest_seasonanchor.list = structuredClone(Array.isArray(Calendar.CalcGB.seasonFest_seasonanchor) ? Calendar.CalcGB.seasonFest_seasonanchor : []);
		this.seasonFest_holyweek.list = structuredClone(Array.isArray(Calendar.CalcGB.seasonFest_holyweek) ? Calendar.CalcGB.seasonFest_holyweek : []);
		this.seasonFest_cron.list = structuredClone(Array.isArray(Calendar.CalcGB.seasonFest_cron) ? Calendar.CalcGB.seasonFest_cron : []);
		this.seasonFest_reference.list = structuredClone(Array.isArray(Calendar.CalcGB.seasonFest_reference) ? Calendar.CalcGB.seasonFest_reference : []);

		// 予定日などの定義 ※基底クラスをオーバーライドする
		this.schedule_fixed.list = structuredClone(Array.isArray(Calendar.CalcGB.schedule_fixed) ? Calendar.CalcGB.schedule_fixed : []);
