	//-------------------------------------------------------------------------
	//
	//	名称	月--->月名
	//	書式	month (月<1-12>) (短縮有無)
	//	機能	月から、月名を取得します。
	//
	//-------------------------------------------------------------------------
	month(month, shortNameFlg) {
		const monthname = {
				  1:'January'
				, 2:'February'
				, 3:'March'
				, 4:'April'
				, 5:'May'
				, 6:'June'
				, 7:'July'
				, 8:'August'
				, 9:'September'
				,10:'October'
				,11:'November'
				,12:'December'
		};
		var name = "";
		if (Number.isInteger(month) && (1 <= month && month <= 12)) {
			if (shortNameFlg) {
				name = monthname[month].slice(0, 3);
			} else {
				name = monthname[month];
			}
		}
		return name;
	}
	//-------------------------------------------------------------------------
	//
	//	名称	曜日--->曜日名
	//	書式	week (曜日<0-6>) (短縮有無)
	//	機能	曜日の数値から、曜日名を取得します。
	//
	//-------------------------------------------------------------------------
	week(dayOfWeek, shortNameFlg) {
		const weekname = {
				  0:'Sunday'
				, 1:'Monday'
				, 2:'Tuesday'
				, 3:'Wednesday'
				, 4:'Thursday'
				, 5:'Friday'
				, 6:'Saturday'
		};
		var name = "";
		if (Number.isInteger(dayOfWeek) && (0 <= dayOfWeek && dayOfWeek <= 6)) {
			if (shortNameFlg) {
				name = weekname[dayOfWeek].slice(0, 3);
			} else {
				name = weekname[dayOfWeek];
			}
		}
		return name;
	}
	//-------------------------------------------------------------------------
	//
	//	名称	協定世界時との差(DSTを考慮しない基準のoffset)
	//
	//-------------------------------------------------------------------------
	offset() {
		return 0; // UTC+0
	}
	//-------------------------------------------------------------------------
	//
	//	名称	ローカル時刻(DSTを考慮しない時刻)
	//
	//-------------------------------------------------------------------------
	#localTime() {
		var	dt = new Calendar.PlainDate();
		dt.minute += this.offset();
		return dt;
	}
